#include "common.h"
namespace gather {
std::vector<std::string> entries(){return {"emult"};}
Input generate(const std::string &entry,uint64_t seed){Input in;in.entry=entry;in.params={{"vlen",65536},{"nnz",8192}};RNG r(seed);auto a=in.add<double>("Ax","f64",8192,"input");auto b=in.add<double>("Bx","f64",65536,"gather");auto bb=in.add<int8_t>("bitmap","i8",65536,"gather");auto i=in.add<int32_t>("Ai","i32",8192,"index");for(int k=0;k<65536;++k){b[k]=int(r.next()%100);bb[k]=r.next()%2;}for(int k=0;k<8192;++k){a[k]=r.next()%100;i[k]=8*k;}in.add<double>("Cx","f64",8192,"output",true);in.add<int32_t>("Ci","i32",8192,"output",true);return in;}
void validate(Input &in){auto n=in.p("vlen",1,10000000),z=in.p("nnz",0,n);finite_values(in.a<double>("Ax","f64",z),z);finite_values(in.a<double>("Bx","f64",n),n);in.a<int8_t>("bitmap","i8",n);index_range(in.a<int32_t>("Ai","i32",z),z,n);in.a<double>("Cx","f64",z);in.a<int32_t>("Ci","i32",z);roles(in,"Ax","input");roles(in,"Bx","gather");roles(in,"bitmap","gather");roles(in,"Ai","index");roles(in,"Cx","output",true);roles(in,"Ci","output",true);}
std::unique_ptr<Case> make_case(const Input &in,Platform &p,bool use_rvv){auto c=std::make_unique<Case>(in,p);auto a=c->work.ptr<double>("Ax"),b=c->work.ptr<double>("Bx"),out=c->work.ptr<double>("Cx");auto bb=c->work.ptr<int8_t>("bitmap");auto i=c->work.ptr<int32_t>("Ai"),ci=c->work.ptr<int32_t>("Ci");auto n=in.params.at("vlen"),z=in.params.at("nnz");c->work.add("Ap",8,"index");c->work.add("Cp",8,"index");c->work.add("tasks",6*sizeof(int64_t),"index");auto ap=c->work.ptr<uint32_t>("Ap"),cp=c->work.ptr<uint32_t>("Cp");auto t=c->work.ptr<int64_t>("tasks");ap[1]=z;for(int64_t k=0;k<z;++k)cp[1]+=bb[i[k]]!=0;t[3]=z;auto fn=SELECT(GB_emult_02a_template,GB_emult_02a_template_rvv);c->call=[=]{fn(i,nullptr,ap,nullptr,nullptr,nullptr,cp,nullptr,a,b,bb,out,ci,nullptr,t,t+1,t+2,t+4,n,1,1,false,false);};return c;}
}
